select count(1)
from sys_industry_ver_conf
where industry_code = #{appCode}
and app_ver_code = #{appVerCode}
and accept_node = #{acceptNode}
and status = '1'
and delete_flag = '0'

select count(1)
from sys_localization_industry_ver_conf
where industry_code = #{appCode}
and app_ver_code = #{appVerCode}
and accept_node = #{acceptNode}
and status = '1'
and delete_flag = '0'

